function getOptionScore(options, value) {
  const option = options.find(item => item.id === value);
  return option ? option.score : 0;
}

function getDay7QuizResults(answer) {
  const part1 = Array.isArray(answer.part1) ? answer.part1 : [];
  const part2 = Array.isArray(answer.part2) ? answer.part2 : [];
  const part1Score = part1.reduce((sum, value) => sum + getOptionScore(EARLY_WARNING_OPTIONS, value), 0);
  const part2Score = part2.reduce((sum, value) => sum + getOptionScore(RISK_FACTOR_OPTIONS, value), 0);
  return {
    early: part1Score <= 30 ? 'LOW' : part1Score <= 45 ? 'MODERATE' : 'HIGH',
    risk: part2Score === 0 ? 'LOW' : part2Score <= 5 ? 'MODERATE' : 'HIGH',
    part1Score,
    part2Score
  };
}

